function syncVisualViewport(){
  const h = window.visualViewport?.height || window.innerHeight || document.documentElement.clientHeight;
  root.style.setProperty('--app-height', `${Math.round(h)}px`);
}
syncVisualViewport();
window.addEventListener('resize', syncVisualViewport, {passive:true});
window.visualViewport?.addEventListener('resize', syncVisualViewport, {passive:true});
window.visualViewport?.addEventListener('scroll', syncVisualViewport, {passive:true});

async function requestGameFullscreen(){
  const target = document.documentElement;
  try{
    if(!document.fullscreenElement && target.requestFullscreen){
      await target.requestFullscreen({navigationUI:'hide'});
    }else if(target.webkitRequestFullscreen){
      target.webkitRequestFullscreen();
    }
  }catch(_){}
  syncVisualViewport();
}

function preventBrowserGesture(e){
  if(e.cancelable) e.preventDefault();
}
document.addEventListener('touchmove', preventBrowserGesture, {passive:false});
document.addEventListener('gesturestart', preventBrowserGesture, {passive:false});
document.addEventListener('contextmenu', e => e.preventDefault());


async function lockLandscape(){
  try{
    if(window.matchMedia('(max-width:900px)').matches && screen.orientation?.lock){
      await screen.orientation.lock('landscape');
    }
  }catch(_){}
}
